import { existsSync } from 'node:fs';
import { z } from 'zod';

/**
 * Every runtime role reads its configuration from the environment, validated here.
 * Locally, values come from the role's gitignored `.env` (generated by
 * `scripts/gen-local-env.mjs` from its `.env.example`); in AWS they come from the task
 * definition and Secrets Manager (milestone MD).
 */
export function loadConfig<S extends z.ZodType>(
  schema: S,
  env: NodeJS.ProcessEnv = process.env,
): z.infer<S> {
  if (env === process.env && existsSync('.env')) {
    process.loadEnvFile('.env');
  }
  const parsed = schema.safeParse(env);
  if (!parsed.success) {
    const missing = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ');
    throw new Error(`Invalid configuration: ${missing}`);
  }
  return parsed.data;
}

const port = z.coerce.number().int().min(1).max(65535);
const url = z.url();
/** Unset and empty both mean "not configured" (templates list every variable). */
const optionalUrl = z.preprocess((v) => (v === '' ? undefined : v), url.optional());
const secret = z.string().min(32, 'must be at least 32 characters');

/** Building blocks shared by the roles' config schemas. */
export const envSchemas = {
  port,
  url,
  optionalUrl,
  secret,
  base: z.object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace']).default('info'),
    OTEL_EXPORTER_OTLP_ENDPOINT: optionalUrl,
  }),
  aws: z.object({
    AWS_REGION: z.string().default('ap-southeast-1'),
    /** LocalStack locally; unset in AWS so the SDK uses the regional endpoint. */
    AWS_ENDPOINT_URL: optionalUrl,
    SQS_TURNS_QUEUE_URL: url,
  }),
  /** The ingestion queue (ADR-018, FEAT-012): scheduler-worker sends, ingest-worker consumes. */
  ingestQueue: z.object({ SQS_INGEST_QUEUE_URL: url }),
  valkey: z.object({ VALKEY_URL: z.string().startsWith('redis') }),
};

export type Env = z.infer<typeof envSchemas.base>;
